CREATE TABLE orders (id BINARY(16) NOT NULL PRIMARY KEY,order_number VARCHAR(40) NOT NULL,user_id BINARY(16) NOT NULL,subtotal DECIMAL(19,2) NOT NULL,discount DECIMAL(19,2) NOT NULL,delivery_fee DECIMAL(19,2) NOT NULL,total_amount DECIMAL(19,2) NOT NULL,status VARCHAR(30) NOT NULL,payment_status VARCHAR(30) NOT NULL,recipient VARCHAR(160) NOT NULL,address_line1 VARCHAR(255) NOT NULL,address_line2 VARCHAR(255),city VARCHAR(100) NOT NULL,state VARCHAR(100) NOT NULL,postal_code VARCHAR(20) NOT NULL,country VARCHAR(100) NOT NULL,phone VARCHAR(30) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_orders_number UNIQUE(order_number));
CREATE INDEX idx_orders_user_created ON orders(user_id,created_at);
CREATE TABLE order_items (id BINARY(16) NOT NULL PRIMARY KEY,order_id BINARY(16) NOT NULL,product_id BINARY(16) NOT NULL,product_name VARCHAR(255) NOT NULL,sku VARCHAR(100) NOT NULL,unit_price DECIMAL(19,2) NOT NULL,quantity INT NOT NULL,line_total DECIMAL(19,2) NOT NULL,CONSTRAINT fk_order_items_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE INDEX idx_order_items_order ON order_items(order_id);
